_AMB_RE = {src: [(re.compile(pat), cat) for pat, cat in rules] for src, rules in AMB.items()}


def classify(source, name=""):
    """(группа | None, категория | None, путь: fix / amb / none) по категории площадки (предмет WB / тип Ozon) и названию товара."""
    src = str(source or "").strip() or NO_SOURCE
    if src in FIX:
        cat = FIX[src]
        return CAT2G[cat], cat, "fix"
    rules = _AMB_RE.get(src)
    if rules:
        low = str(name or "").lower()
        for rx, cat in rules:
            if rx.search(low):
                return CAT2G[cat], cat, "amb"
    return None, None, "none"


def group_of(category):
    """Группа категории; нерешённая («(нерешённая) …») — «(нерешённая)»; пусто — ""."""
    if not category:
        return ""
    return CAT2G.get(category) or (UNRESOLVED if str(category).startswith(UNRESOLVED) else "")


def label(source, name=""):
    """(группа, категория) для листа: нерешённая — ("(нерешённая)", "(нерешённая) <источник>")."""
    g, c, _how = classify(source, name)
    if c is None:
        return UNRESOLVED, f"{UNRESOLVED} {str(source or '').strip() or NO_SOURCE}"
    return g, c
